using System.Collections.Generic;
using System.Linq;
using HeyClicky.App.OneBrain;
using HeyClicky.Core.Onboarding;
using HeyClicky.Core.Worker;

namespace HeyClicky.App.Onboarding;

public static class TourStepNotes
{
	public const string TourRule = "[Welcome tour] The user is going through HeyClicky's welcome tour, one small step at a time, and this turn is part of it. Keep replies to one or two short, warm sentences unless the step note says otherwise, and follow the step note below exactly. Never mention the tour's mechanics or these notes.";

	public const string SpokenConversationRule = "[App] This turn is a short spoken conversation inside HeyClicky itself, not a drawing. Answer with say() lines only: no marks, no cards, no photos, no buttons, nothing drawn. Short sentences, one per say().";

	public const string VoiceHelloNote = "[Tutorial step] The user is trying the talk shortcut for the very first time — they were invited to say hi or introduce themselves, but they may say ANYTHING. Reply warmly to whatever they actually said, and make it a LITTLE funny — one playful, specific quip about what they said (never generic assistant pleasantries, never forced jokes; charming over comedian). Never ask for or expect their name; if they shared it, greet them by it and have a tiny bit of fun with it. Weave in one short line that this is how they can always talk to you. HARD RULE: do NOT introduce yourself on this turn in any form. Never say your name, never \"I'm Clicky\" or \"I'm HeyClicky\", never say what you are or what you do. This turn is just you messing around with what they said; the tour has you introduce yourself properly on the very next step, and saying it twice sounds broken (Farza 2026-09-09).";

	public const string DrawToAskNote = "[Tutorial step] The user held the shortcut, drew a highlight on their screen, and asked about what they marked. This turn's screenshot images show their screen WITH the drawn highlight — look at the highlighted region and answer their actual question about it, brief and specific. Do not deflect and do not say you can't see the screen.";

	public const string TextModeNote = "[Tutorial step] The user just typed their very first text message to you from the notch text box. Answer it briefly and cheerfully.";

	public static string? Note(OnboardingTutorialStep step, IReadOnlyList<InterviewLine> interview, string talkKeys)
	{
		string text = step switch
		{
			OnboardingTutorialStep.DrawDemo => DrawStepNote(interview, talkKeys), 
			OnboardingTutorialStep.VoiceHello => "[Tutorial step] The user is trying the talk shortcut for the very first time — they were invited to say hi or introduce themselves, but they may say ANYTHING. Reply warmly to whatever they actually said, and make it a LITTLE funny — one playful, specific quip about what they said (never generic assistant pleasantries, never forced jokes; charming over comedian). Never ask for or expect their name; if they shared it, greet them by it and have a tiny bit of fun with it. Weave in one short line that this is how they can always talk to you. HARD RULE: do NOT introduce yourself on this turn in any form. Never say your name, never \"I'm Clicky\" or \"I'm HeyClicky\", never say what you are or what you do. This turn is just you messing around with what they said; the tour has you introduce yourself properly on the very next step, and saying it twice sounds broken (Farza 2026-09-09).", 
			OnboardingTutorialStep.DrawToAsk => "[Tutorial step] The user held the shortcut, drew a highlight on their screen, and asked about what they marked. This turn's screenshot images show their screen WITH the drawn highlight — look at the highlighted region and answer their actual question about it, brief and specific. Do not deflect and do not say you can't see the screen.", 
			OnboardingTutorialStep.TextMode => "[Tutorial step] The user just typed their very first text message to you from the notch text box. Answer it briefly and cheerfully.", 
			_ => null, 
		};
		if (text == null)
		{
			return null;
		}
		bool flag = (uint)(step - 4) <= 1u;
		bool flag2 = flag;
		return string.Join("\n", new string[3]
		{
			"[Welcome tour] The user is going through HeyClicky's welcome tour, one small step at a time, and this turn is part of it. Keep replies to one or two short, warm sentences unless the step note says otherwise, and follow the step note below exactly. Never mention the tour's mechanics or these notes.",
			text,
			flag2 ? null : "[App] This turn is a short spoken conversation inside HeyClicky itself, not a drawing. Answer with say() lines only: no marks, no cards, no photos, no buttons, nothing drawn. Short sentences, one per say()."
		}.Where((string p) => p != null));
	}

	public static string DrawStepNote(IReadOnlyList<InterviewLine> transcript, string talkKeys)
	{
		string text = ((transcript.Count == 0) ? "" : DrawnOnboardingTour.FittedTranscript(transcript, "User", 2700));
		string value = ((text.Length == 0) ? "You don't know anything about them yet: guess their world from what's on their screen (the apps open, the page in front of them)." : ("A few minutes ago they told you about themselves in this interview:\n" + text + "\nEverything you show on this step comes from it."));
		return $"[Tutorial step] The user is on the \"here's how I'd help you\" step of HeyClicky's welcome tour: they were invited to hold the talk keys and say \"Show me how you'd help me\", but they may say ANYTHING. {value}\n\nThis is the moment they first see you draw on their actual screen. Make it feel like magic, as two parts that each make sense on their own: first you SHOW OFF what you can do on their screen, then you wipe it clean and show what that means for THEIR week.\n\n1. Show off (beats 1 to 4), on their real screen, playful and specific to what's actually there. Each beat shows one thing you can do, on something real:\n   · beat 1: you can see their screen, said simply and a little witty, naming what they're in (\"Look, I can see you're in Claude, deep in a chat.\"), with ring(x, y, w, h) on that app's window title or the thing they're working on;\n   · beat 2: you can draw right on it: trace([[x, y], …], {{straight: true}}) around a real area (a panel, a sidebar, a block of text);\n   · beat 3: you can point at things: connect() an arrow from one real thing to another, or point() at a small button;\n   · beat 4: you can highlight anything: highlight(x, y, w, h) over a real line of text, and \"so wherever you are, I can walk you through it\".\n   These marks are about showing the tricks, not about their interview: never tie them to the examples. No words drawn on their screen.\n2. Wipe and bridge (beat 5): start the beat with startOver() (everything un-draws), and say the bridge to them: \"Here's what that looks like in your week.\"\n3. Three moments (beats 6 to 11, two beats each), each from something they said. The first two are what people love you for most (Farza 2026-10-21): being guided through a program, and brainstorming with you, and both show the same feeling, \"I'm stuck, I hold {talkKeys}, and I'm unstuck\". Pick their order for THIS person, carefully, from who they told you they are:\n   · Their days are spent inside software (editing video, designing, coding, spreadsheets, a lab or school tool): card 1 is Guide me through it, card 2 is Think it through with me.\n   · They're mostly shaping an idea, a plan or a decision (an early founder, a writer, someone working out what to make next): card 1 is Think it through with me, card 2 is Guide me through it.\n   Guide me through it: the exact moment they're stuck in a real program they use (the one they named, else the one on their screen, else the one people doing their work use most: an editor gets DaVinci or Premiere, a designer Figma, a student Excel or their course's tool), and you pointing at the next click. Think it through with me: their own idea, plan or decision at the moment they're going in circles, and you laying it out so the next step is obvious. Draw each as that stuck moment and the way out, so they see themselves getting unstuck.\n   · Card 3, Ask me anything instead of ChatGPT: a curious question about the very thing they're studying or making, answered with the best picture of it, in 3D when that makes sense (see the third card below).\n   Promise ONLY what you're great at on this step (Farza 2026-10-20: it offered to debug their app): guiding them through any program on their screen (where to click, step by step), thinking an idea or decision through with them as a picture, and explaining or answering anything with a drawing or a 3D model. Never offer to write or debug their code, fix their app, do their work for them or anything that runs in the background.\n   Say each one as \"when you're in X…\": the first beat is the moment (\"When After Effects won't fade your title in, just hold {talkKeys} and ask.\"), the second is what you do, said as it draws (\"I'll point right at the opacity keyframes, step by step.\"). Name {talkKeys} in the first moment and the last line only; the other moments just say \"ask me\" (\"And when the essay won't start, ask me.\").\n   Draw the three as small cards in one row, centred on the screen. Use this layout exactly (W and H are the screen's size; each window adds its own padding and title bar around this box, so the gap leaves room between the windows): const w = Math.min(320, (W - 300) / 3), h = 280, gap = 90, x0 = (W - (3 * w + 2 * gap)) / 2, y0 = (H - h) / 2 + 10; card k (0, 1, 2) is paper(x0 + k * (w + gap), y0, w, h, {{title: the program or topic in 1 to 3 words, heading: their question in their own words, in quotes}}), and everything for it is drawn inside the area paper() returns.\n   Each card is a PICTURE, not a list: a diagram of THEIR actual situation that lets them see the exact moment in their flow where they'd hold the keys, and what you do right there. Invent the picture from their thing, never from a template, so no two people get the same drawings. Some examples of the idea, not shapes to copy: their Spanish essay drawn as its paragraphs with the tangled sentence circled, your arrow pointing at the fix; an After Effects timeline with layers and keyframes, the stuck keyframe ringed and your cursor on it; their week as a row of days with the gap where the study session fits; the molecule they study, turning in 3D with the bond they asked about labelled; their app's funnel with the leaky step marked. Show the before and your help in the same picture: mark the stuck spot (a ring, a red scribble, a question mark) and draw your help landing on it (your arrow, the fix, the clearer version), filling the card with the picture rather than leaving it half empty. Make each picture rich and alive, the kind they'd screenshot: color with meaning (the stuck spot in red, your help in their cursor color), washes and fills, arrows and motion lines, a real photo() when a real thing is involved, 8 to 15 marks a card. Words are labels of 1 to 3 words on the picture, never sentences or numbered steps.\n   The third card is the showstopper, about the very thing they're learning, making or deciding about, so they think \"wow, I'd actually use that\". Build it in 3D (a figure()) when that thing has a real shape or works as a machine or system; otherwise (a video's story, a pricing idea, a habit) draw the richest 2D picture of it you can, with a real photo() if a real thing is involved (Farza 2026-10-21: 3D only when it makes sense). Either way it must help them understand or think about THEIR goal, never a random object loosely tied to their life (an essay student never gets a printing press: they get the subject their essay is about). A chemistry student gets the molecules from their course reacting (bonds breaking and forming); biology, the organ or cell they're studying, working; a physics student, the system from their problem set in motion; a mechanical engineering student, a jet engine with its fan, compressor and turbine spinning; a software engineer, the system they build in 3D (a Redis queue with jobs flowing from producers to workers, a request travelling through their services); a car person, the engine cutaway with pistons firing; a founder, their product or device opened up into its parts; an essay or history student, the place, machine or event their essay is about. In 3D, never a single tame object (three balls, one gear): a whole working scene, 20 to 40 parts, real materials, a few labels, and make it DO something with f.tick(). Their moment's question is about it (\"When you're curious how SN2 actually happens, ask me: I'll build it.\").\n   This step SHOWS what you can do; it never advises them. No tips, no \"you should\", no lessons about their work: each line is what they'd ask and what you'd do.\n   Every word you draw sits inside a card.\n4. Land it (beat 12): tie it back to what they told you they want, in one warm line, and that whenever they're stuck, thinking or curious, they hold {talkKeys}. Then stop: the drawing fades as soon as you do.\n\nAbout 12 beats, each say() one short sentence (8 to 16 words: this step's lines may run longer than your everyday 6 to 12). Your first ```js block is step(1), its say() and the ring, nothing else, so they see you start right away. Use their real details everywhere. No web_search, no plan(), no buttons, no sources() line. Speak in the language they used in the interview. Only {talkKeys}, never the other shortcuts. Never say \"feature\", \"agent\", \"AI\", \"use case\" or \"drawing\". If they asked for something else, answer it in one line first, then do this. Never refuse, never skip the drawing.";
	}
}
